<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>About · Acme Storefront</title>
  <link rel="stylesheet" href="css/tokens.css">
  <link rel="stylesheet" href="css/base.css">
  <link rel="stylesheet" href="css/components.css">
  <link rel="stylesheet" href="css/pages.css">
</head>
<body class="page-about">
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="index.html">
        <img class="brand-mark" src="assets/logo.svg" width="28" height="28" alt="">
        <span class="brand-name">Acme Storefront</span>
      </a>
      <button class="nav-toggle" type="button" aria-label="Menu" aria-expanded="false" aria-controls="site-nav">
        <span class="nav-toggle-bar"></span>
        <span class="nav-toggle-bar"></span>
        <span class="nav-toggle-bar"></span>
      </button>
      <nav class="site-nav" id="site-nav" aria-label="Main">
        <a class="nav-link" href="index.html">Home</a>
        <a class="nav-link" href="products.html">Products</a>
        <a class="nav-link" href="pricing.html">Pricing</a>
        <a class="nav-link" href="orders.html">Orders</a>
        <a class="nav-link" href="about.html" aria-current="page">About</a>
        <a class="nav-link" href="contact.html">Contact</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="container page-head">
      <h1>About</h1>
      <p class="lede">Four people and a workshop by the harbour.</p>
    </div>

    <section class="section">
      <div class="container story">
        <div>
          <h2 class="section-title">How it started</h2>
          <p>Acme began with one lamp, built for a desk that was too dark in winter. Friends asked for one, then friends of friends.</p>
          <p>We still make everything in small batches, and we still answer every email ourselves.</p>
        </div>
        <img class="story-art" src="assets/workshop.png" width="480" height="300" alt="The workshop, a white house with a red roof next to a warehouse">
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="section-title">The team</h2>
        <div class="cards cards-4">
          <div class="card member">
            <div class="card-body">
              <div class="avatar">MO</div>
              <h3>Mira Okafor</h3>
              <p>Founder, lamps</p>
            </div>
          </div>
          <div class="card member">
            <div class="card-body">
              <div class="avatar">TB</div>
              <h3>Tomas Berg</h3>
              <p>Workshop</p>
            </div>
          </div>
          <div class="card member">
            <div class="card-body">
              <div class="avatar">LS</div>
              <h3>Lena Sato</h3>
              <p>Orders and support</p>
            </div>
          </div>
          <div class="card member">
            <div class="card-body">
              <div class="avatar">JR</div>
              <h3>Jonah Reyes</h3>
              <p>Design</p>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <h2 class="section-title">So far</h2>
        <ol class="timeline">
          <li class="timeline-item">
            <p class="timeline-year">2021</p>
            <p>The first Aurora Lamp, sold to a neighbour.</p>
          </li>
          <li class="timeline-item">
            <p class="timeline-year">2023</p>
            <p>The workshop by the harbour opens.</p>
          </li>
          <li class="timeline-item">
            <p class="timeline-year">2025</p>
            <p>Ten thousand orders shipped.</p>
          </li>
        </ol>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="cta">
          <div>
            <h2>Want something made for your office?</h2>
            <p>Tell us what you need and we will send a quote.</p>
          </div>
          <a class="btn btn-primary btn-lg" href="contact.html">Get in touch</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <p>© 2026 Acme Storefront. Small things for busy desks.</p>
      <div class="footer-links">
        <a href="about.html">About</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </footer>

  <script src="js/app.js"></script>
</body>
</html>
/* Reset, typography and page layout. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-ink);
  background: var(--color-bg);
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-brand);
}

[hidden] {
  display: none !important;
}

h1 {
  font-size: 36px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
}

h3 {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
}

.page-head {
  padding-top: var(--space-7);
}

.page-head .lede {
  max-width: 640px;
  margin-top: var(--space-3);
}

.lede {
  font-size: 18px;
  color: var(--color-muted);
}

.muted {
  color: var(--color-muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (max-width: 720px) {
  h1 {
    font-size: 28px;
  }

  h2 {
    font-size: 21px;
  }

  .container {
    padding: 0 var(--space-4);
  }

  .section,
  .page-head {
    padding-top: var(--space-6);
  }
}
/* Shared components: header, button, card, form, table, modal, and friends. */

/* Header */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-ink);
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 600;
  color: var(--color-ink);
  text-decoration: none;
}

.nav-link:hover {
  background: var(--color-bg);
}

.nav-link[aria-current='page'] {
  color: var(--color-brand);
  background: var(--color-brand-tint);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  cursor: pointer;
}

.nav-toggle-bar {
  display: block;
  width: 18px;
  height: 2px;
  margin: 4px auto;
  border-radius: 1px;
  background: var(--color-ink);
}

/* Button */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font: inherit;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  text-decoration: none;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-brand);
  color: #ffffff;
}

.btn-primary:hover {
  background: var(--color-brand-dark);
}

.btn-secondary {
  background: var(--color-surface);
  color: var(--color-ink);
  border-color: var(--color-line);
}

.btn-secondary:hover {
  background: var(--color-bg);
}

.btn-sm {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
}

.btn-lg {
  padding: 13px 24px;
  font-size: 16px;
}

.btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Card */

.card {
  position: relative;
  background: var(--color-surface);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.card-body {
  padding: var(--space-5);
}

.card-thumb {
  height: 120px;
  border-radius: 13px 13px 0 0;
}

.card h3 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 15px;
  color: var(--color-muted);
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

